function cleanName(fullName) {
  if (!fullName) return { nombre: '', apellidos: [] };

  fullName = fullName
    .replace(/^Don\s+/i, '')
    .replace(/^Doña\s+/i, '')
    .trim();

  const partes = fullName.split(/\s+/);
  if (partes.length === 1) return { nombre: partes[0], apellidos: [] };

  return {
    nombre: partes[0],
    apellidos: partes.slice(1)
  };
}

function cleanString(str) {
  return str
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')  
    .replace(/[^a-z]/g, '');
}

function cleanDomain(str) {
  return (str || '')
    .replace(/^https?:\/\//, '')
    .replace(/^www\./, '')
    .trim()
    .toLowerCase();
}

function generateLikelyEmails(nombre, apellidos, dominio) {
  const emails = new Set();

  const n = cleanString(nombre);
  const ap = apellidos.map(a => cleanString(a)).filter(Boolean);

  const primerApellido = ap[0] || '';
  const segundoApellido = ap[1] || '';

  const ni = n.charAt(0);
  const pai = primerApellido.charAt(0);

  // LISTA PRIORITARIA = correos más probables
  const combos = [
    `${n}`,                                 // maria
    `${primerApellido}`,                    // saez
    `${n}${primerApellido}`,                // mariasaez
    `${n}.${primerApellido}`,               // maria.saez
    `${n}_${primerApellido}`,               // maria_saez
    `${n}-${primerApellido}`,               // maria-saez

    `${primerApellido}${segundoApellido}`,  // saezgil
    `${primerApellido}.${segundoApellido}`, // saez.gil
    `${primerApellido}_${segundoApellido}`, // saez_gil
    `${primerApellido}-${segundoApellido}`, // saez-gil

    `${ni}${primerApellido}`,               // msaez
    `${ni}.${primerApellido}`,              // m.saez

    `${n}${segundoApellido}`,               // mariagil (menos común pero posible)
    `${ni}${segundoApellido}`,              // mgil

    `${primerApellido}${ni}`,               // saezm
    `${primerApellido}.${ni}`,              // saez.m

    `${n}${primerApellido}${segundoApellido}`, // mariasaezgil

    `${n}${pai}`,                           // mariay
    `${ni}${primerApellido}${pai}`,         // msaezg
  ];

  combos.forEach(c => {
    if (c && dominio) emails.add(`${c}@${dominio}`);
  });

  return Array.from(emails).slice(0, 20);
}

